    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r-1][c] == 2 and grid[r+1][c] == 2
                    and grid[r][c-1] == 2 and grid[r][c+1] == 2):
                centers.append((r, c))
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i+1:]:
            if r1 == r2 and not any(r == r1 and min(c1, c2) < c < max(c1, c2) for r, c in centers):
                lo, hi = sorted((c1, c2))
                for c in range(lo + 2, hi - 1):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2 and not any(c == c1 and min(r1, r2) < r < max(r1, r2) for r, c in centers):
                lo, hi = sorted((r1, r2))
                for r in range(lo + 2, hi - 1):
                    if out[r][c1] == 0:
                        out[r][c1] = 1
    return out
